        m_agent_pane->web_view().host().tools().set_earlier_projects({}, {}, {});
        m_agent_pane->Destroy();
        m_agent_pane = nullptr;
    }
    if (m_printer_panel != nullptr) {
        m_printer_panel->Destroy();
        m_printer_panel = nullptr;
    }
    if (m_home != nullptr) {
        m_home->Destroy();
        m_home = nullptr;
    }
