// node filter-diff.mjs <in.diff> <out.diff> <spec.json>
// spec: { dropHunk: [substr...], dropLine: [substr...] }
// Drops whole hunks containing any dropHunk substring; drops '+' lines
// containing any dropLine substring from the hunks kept.
import fs from 'node:fs';
const [, , input, output, specPath] = process.argv;
const spec = JSON.parse(fs.readFileSync(specPath, 'utf8'));
const lines = fs.readFileSync(input, 'utf8').split('\n');
const header = [];
const hunks = [];
for (const line of lines) {
  if (line.startsWith('@@')) hunks.push([line]);
  else if (hunks.length) hunks[hunks.length - 1].push(line);
  else header.push(line);
}
const out = [...header];
let dropped = 0, droppedLines = 0;
for (const hunk of hunks) {
  if (hunk.some(l => (spec.dropHunk || []).some(s => l.includes(s)))) { dropped++; continue; }
  for (const l of hunk) {
    if (l.startsWith('+') && (spec.dropLine || []).some(s => l.includes(s))) { droppedLines++; continue; }
    out.push(l);
  }
}
fs.writeFileSync(output, out.join('\n'));
console.log(`${input}: kept ${hunks.length - dropped} of ${hunks.length} hunks, dropped ${droppedLines} lines`);
